/* ==========================================================
   SORRISO NOBLE — Comportamento
   Vanilla JS, sem dependências. Depende de js/data.js (window.SN).
   ========================================================== */
(function () {
  "use strict";

  var D = window.SN;
  if (!D) return;

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var $$ = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };
  var pad = function (n) { return (n < 10 ? "0" : "") + n; };

  /* ---------- WhatsApp ---------- */
  function waLink(message) {
    return "https://wa.me/" + D.whatsapp + "?text=" + encodeURIComponent(message || D.defaultMessage);
  }

  function treatmentMessage(t) {
    return "Olá! Gostaria de agendar uma Avaliação Exclusiva na Sorriso Noble para " + t.title + ".";
  }

  /* Foto embutida (data URI) dentro do arco; decorativa, pois o texto da linha já descreve o tratamento */
  function mediaMarkup(src, focus) {
    var pos = focus ? ' style="object-position:' + focus + '"' : "";
    return '<img src="' + src + '" alt="" loading="lazy" decoding="async"' + pos + '>';
  }

  /* ---------- Tratamentos: índice, filtro e preview ---------- */
  var filtersEl = $("#filters");
  var listEl = $("#specialty-list");
  var previewEl = $("#preview");
  var statusEl = $("#filter-status");

  function renderTreatments() {
    if (!listEl) return;

    filtersEl.innerHTML = D.filters.map(function (f, i) {
      return '<button class="chip" type="button" data-filter="' + f.id + '" aria-pressed="' + (i === 0) + '">' + f.label + "</button>";
    }).join("");

    listEl.innerHTML = D.treatments.map(function (t, i) {
      return (
        '<li class="row" data-id="' + t.id + '" data-cat="' + t.category + '" data-reveal style="--d:' + i * 60 + 'ms">' +
          '<span class="row__n" aria-hidden="true">' + pad(i + 1) + "</span>" +
          '<div class="row__body">' +
            '<h3 class="row__t">' + t.title + "</h3>" +
            '<p class="row__d">' + t.description + "</p>" +
            '<ul class="row__tags" aria-label="Categoria"><li>' + t.categoryLabel + "</li></ul>" +
          "</div>" +
          '<figure class="arch row__thumb" style="--ar:' + t.ratio + '" aria-hidden="true">' + mediaMarkup(t.image, t.focus) + "</figure>" +
          '<a class="link row__cta" href="' + waLink(treatmentMessage(t)) + '" target="_blank" rel="noopener">' +
            'Agendar <span aria-hidden="true">↗</span>' +
            '<span class="sr-only"> avaliação para ' + t.title + " (abre o WhatsApp)</span>" +
          "</a>" +
        "</li>"
      );
    }).join("");

    previewEl.innerHTML = D.treatments.map(function (t) {
      return '<div class="preview__item" data-id="' + t.id + '">' + mediaMarkup(t.image, t.focus) + "</div>";
    }).join("");

    setActive(D.treatments[0].id);
  }

  function setActive(id) {
    $$(".row", listEl).forEach(function (r) { r.classList.toggle("is-active", r.dataset.id === id); });
    $$(".preview__item", previewEl).forEach(function (p) { p.classList.toggle("is-active", p.dataset.id === id); });
    /* o arco acompanha a proporção da foto ativa, para ela preencher o campo todo */
    D.treatments.forEach(function (t) { if (t.id === id && t.ratio) previewEl.style.setProperty("--ar", t.ratio); });
  }

  function applyFilter(id) {
    var shown = 0;
    $$(".row", listEl).forEach(function (row) {
      var visible = id === "todos" || row.dataset.cat === id;
      row.hidden = !visible;
      row.classList.remove("is-entering");
      if (visible) {
        row.classList.add("is-in");
        row.style.setProperty("--d", shown * 70 + "ms");
        void row.offsetWidth; /* reinicia a animação */
        row.classList.add("is-entering");
        shown++;
      }
    });

    $$(".chip", filtersEl).forEach(function (c) { c.setAttribute("aria-pressed", String(c.dataset.filter === id)); });

    var first = $(".row:not([hidden])", listEl);
    if (first) setActive(first.dataset.id);
    statusEl.textContent = "Mostrando " + shown + (shown === 1 ? " tratamento" : " tratamentos") + ".";
  }

  function bindTreatments() {
    if (!listEl) return;

    filtersEl.addEventListener("click", function (e) {
      var chip = e.target.closest(".chip");
      if (chip) applyFilter(chip.dataset.filter);
    });

    listEl.addEventListener("mouseover", function (e) {
      var row = e.target.closest(".row");
      if (row) setActive(row.dataset.id);
    });
    listEl.addEventListener("focusin", function (e) {
      var row = e.target.closest(".row");
      if (row) setActive(row.dataset.id);
    });
  }

  /* ---------- Etapas da avaliação ---------- */
  function renderSteps() {
    var el = $("#steps");
    if (!el) return;
    el.innerHTML = D.steps.map(function (s, i) {
      return (
        '<li class="step" data-reveal style="--d:' + i * 140 + 'ms">' +
          '<span class="step__n">' + pad(i + 1) + "</span>" +
          '<h3 class="step__t">' + s.title + "</h3>" +
          '<p class="step__d">' + s.text + "</p>" +
        "</li>"
      );
    }).join("");
  }

  /* ---------- Números ---------- */
  function renderStats() {
    var el = $("#stats");
    if (!el) return;
    el.innerHTML = D.stats.map(function (s, i) {
      return (
        '<div class="stat" data-reveal style="--d:' + i * 120 + 'ms">' +
          '<dt class="stat__l">' + s.label + "</dt>" +
          '<dd class="stat__v">' + s.value + "</dd>" +
          '<dd class="stat__t">' + s.text + "</dd>" +
        "</div>"
      );
    }).join("");
  }

  /* ---------- FAQ (acordeão acessível) ---------- */
  function renderFaq() {
    var el = $("#faq-list");
    if (!el) return;

    el.innerHTML = D.faq.map(function (f, i) {
      var n = i + 1;
      return (
        '<div class="acc" data-reveal style="--d:' + i * 80 + 'ms">' +
          '<h3><button class="acc__btn" type="button" id="acc-btn-' + n + '" aria-expanded="false" aria-controls="acc-panel-' + n + '">' +
            "<span>" + f.q + '</span><span class="acc__icon" aria-hidden="true"></span>' +
          "</button></h3>" +
          '<div class="acc__panel" id="acc-panel-' + n + '" role="region" aria-labelledby="acc-btn-' + n + '">' +
            '<div class="acc__inner"><p>' + f.a + "</p></div>" +
          "</div>" +
        "</div>"
      );
    }).join("");

    el.addEventListener("click", function (e) {
      var btn = e.target.closest(".acc__btn");
      if (!btn) return;
      var open = btn.getAttribute("aria-expanded") === "true";

      $$(".acc__btn", el).forEach(function (b) {
        b.setAttribute("aria-expanded", "false");
        document.getElementById(b.getAttribute("aria-controls")).classList.remove("is-open");
      });

      if (!open) {
        btn.setAttribute("aria-expanded", "true");
        document.getElementById(btn.getAttribute("aria-controls")).classList.add("is-open");
      }
    });
  }

  /* ---------- Links de WhatsApp com mensagem própria ---------- */
  function bindWhatsAppLinks() {
    $$("[data-wa]").forEach(function (a) { a.href = waLink(a.getAttribute("data-wa")); });
  }

  /* ---------- Modal de pré-agendamento ---------- */
  var modal = $("#booking");
  var form = $("#booking-form");

  function fillTreatmentSelect() {
    var sel = $("#f-treatment");
    if (!sel) return;
    sel.innerHTML =
      '<option value="">Ainda não sei, quero uma orientação</option>' +
      D.treatments.map(function (t) { return '<option value="' + t.title + '">' + t.title + "</option>"; }).join("");
  }

  function openBooking() {
    if (!modal) return;
    if (typeof modal.showModal === "function") {
      modal.showModal();
      document.documentElement.classList.add("modal-open");
      document.body.classList.add("is-locked");
      var name = $("#f-name");
      if (name) name.focus();
    } else {
      window.open(waLink(), "_blank", "noopener");
    }
  }

  function closeBooking() { if (modal && modal.open) modal.close(); }

  function bindModal() {
    if (!modal) return;

    $$("[data-open-booking]").forEach(function (b) {
      b.addEventListener("click", function () {
        closeMenu();
        openBooking();
      });
    });

    $$("[data-close-booking]").forEach(function (b) { b.addEventListener("click", closeBooking); });

    modal.addEventListener("click", function (e) { if (e.target === modal) closeBooking(); });
    modal.addEventListener("close", function () { document.body.classList.remove("is-locked"); });

    var nameInput = $("#f-name");
    var nameErr = $("#f-name-err");

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var name = nameInput.value.trim();

      if (!name) {
        nameInput.setAttribute("aria-invalid", "true");
        nameInput.setAttribute("aria-describedby", "f-name-err");
        nameErr.hidden = false;
        nameInput.focus();
        return;
      }

      nameInput.removeAttribute("aria-invalid");
      nameErr.hidden = true;

      var treatment = $("#f-treatment").value;
      var period = $("#f-period").value;
      var msg = "Olá! Meu nome é " + name + ". Gostaria de agendar uma Avaliação Exclusiva" +
        (treatment ? " para " + treatment : "") + ". Melhor horário: " + period + ".";

      window.open(waLink(msg), "_blank", "noopener");
      closeBooking();
      form.reset();
    });

    nameInput.addEventListener("input", function () {
      if (nameInput.value.trim()) {
        nameInput.removeAttribute("aria-invalid");
        nameErr.hidden = true;
      }
    });
  }

  /* ---------- Header e menu mobile ---------- */
  var header = $("#header");
  var menu = $("#menu");
  var toggle = $("#menu-toggle");

  function openMenu() {
    header.classList.add("menu-open");
    menu.classList.add("is-open");
    menu.inert = false;
    toggle.setAttribute("aria-expanded", "true");
    toggle.querySelector(".sr-only").textContent = "Fechar menu";
    document.body.classList.add("is-locked");
  }

  function closeMenu() {
    if (!menu) return;
    header.classList.remove("menu-open");
    menu.classList.remove("is-open");
    menu.inert = true;
    toggle.setAttribute("aria-expanded", "false");
    toggle.querySelector(".sr-only").textContent = "Abrir menu";
    if (!(modal && modal.open)) document.body.classList.remove("is-locked");
  }

  function bindHeader() {
    toggle.addEventListener("click", function () {
      if (menu.classList.contains("is-open")) closeMenu(); else openMenu();
    });
    $$("[data-menu-link]").forEach(function (l) { l.addEventListener("click", closeMenu); });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && menu.classList.contains("is-open")) { closeMenu(); toggle.focus(); }
    });
    window.matchMedia("(min-width: 1025px)").addEventListener("change", function (e) { if (e.matches) closeMenu(); });
  }

  /* ---------- Reveal ao rolar ---------- */
  var revealObserver = null;

  function observeReveals() {
    var items = $$("[data-reveal]:not(.is-in)");
    if (reduceMotion || !("IntersectionObserver" in window)) {
      items.forEach(function (el) { el.classList.add("is-in"); });
      return;
    }
    if (!revealObserver) {
      revealObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            revealObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.12, rootMargin: "0px 0px -6% 0px" });
    }
    items.forEach(function (el) { revealObserver.observe(el); });
  }

  /* ---------- Scroll: header, parallax sutil, FAB ---------- */
  var parallaxEls = [];
  var fab = $("#fab");
  var hero = $("#inicio");
  var ticking = false;

  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () {
      var y = window.scrollY;
      header.classList.toggle("is-scrolled", y > 24);

      if (fab && hero) {
        var past = y > hero.offsetHeight * 0.7;
        fab.classList.toggle("is-visible", past);
      }

      if (!reduceMotion) {
        var vh = window.innerHeight;
        parallaxEls.forEach(function (el) {
          var rect = el.parentElement.getBoundingClientRect();
          if (rect.bottom < -200 || rect.top > vh + 200) return;
          var speed = parseFloat(el.getAttribute("data-parallax")) || 0;
          var offset = (rect.top + rect.height / 2 - vh / 2) * speed;
          offset = Math.max(-40, Math.min(40, offset)); /* teto de 40px */
          el.style.setProperty("--py", offset.toFixed(1) + "px");
        });
      }
      ticking = false;
    });
  }

  /* ---------- Init ---------- */
  function init() {
    renderTreatments();
    renderSteps();
    renderStats();
    renderFaq();
    fillTreatmentSelect();

    bindTreatments();
    bindWhatsAppLinks();
    bindModal();
    bindHeader();

    parallaxEls = $$("[data-parallax]");
    observeReveals();

    var year = $("#year");
    if (year) year.textContent = new Date().getFullYear();

    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    onScroll();

    /* dispara a entrada do hero depois do primeiro frame */
    requestAnimationFrame(function () {
      requestAnimationFrame(function () { document.documentElement.classList.add("is-ready"); });
    });
  }

  init();
})();